#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int isp(long long v){if(v<2)return 0;long long d;for(d=2;d*d<=v;d++)if(v%d==0)return 0;return 1;}int main(void){int n,i;static long long a[500005];if(scanf("%d",&n)!=1)return 1;for(i=0;i<n;i++)scanf("%lld",&a[i]);long long s=0;int c=0;for(i=0;i<n;i++){long long x=a[i];if(isp(x)){s+=x;c++;}}printf("%lld\n",c?s/c:-1);return 0;}
